-- Functions, with their EXECUTE grants re-applied
-- Generated by scripts/snapshot-schema.mts from the live database. Do not edit by hand;
-- change the database, then re-run the script.

CREATE OR REPLACE FUNCTION public.admin_export_player_rows(uid uuid, tbls jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  t jsonb;
  rows jsonb;
  out jsonb := '{}'::jsonb;
begin
  for t in select * from jsonb_array_elements(tbls) loop
    if to_regclass('public.' || quote_ident(t->>'table')) is null then
      raise exception 'unknown table %', t->>'table';
    end if;
    execute format('select coalesce(jsonb_agg(to_jsonb(x)), ''[]''::jsonb) from public.%I x where x.%I = $1',
      t->>'table', t->>'col') into rows using uid;
    out := out || jsonb_build_object(t->>'table', rows);
  end loop;
  return out;
end
$function$
;
revoke all on function public.admin_export_player_rows(uid uuid, tbls jsonb) from public, anon, authenticated;
grant execute on function public.admin_export_player_rows(uid uuid, tbls jsonb) to service_role;

CREATE OR REPLACE FUNCTION public.admin_import_player_rows(uid uuid, profile jsonb, tbls jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  t jsonb;
  cols text;
  sets text;
  n int;
  report jsonb := '{}'::jsonb;
  i int;
begin
  for t in select * from jsonb_array_elements(tbls) loop
    if to_regclass('public.' || quote_ident(t->>'table')) is null then
      raise exception 'unknown table %', t->>'table';
    end if;
  end loop;

  for i in reverse jsonb_array_length(tbls) - 1 .. 0 loop
    t := tbls->i;
    execute format('delete from public.%I where %I = $1', t->>'table', t->>'col') using uid;
  end loop;

  if profile is not null then
    select string_agg(format('%I = r.%I', a.attname, a.attname), ', ')
      into sets
      from pg_attribute a
      where a.attrelid = 'public.profiles'::regclass and a.attnum > 0 and not a.attisdropped
        and a.attgenerated = '' and a.attname <> 'id' and profile ? a.attname;
    if sets is not null then
      execute format('update public.profiles p set %s from jsonb_populate_record(null::public.profiles, $1) r where p.id = $2', sets)
        using profile, uid;
    end if;
  end if;

  for i in 0 .. jsonb_array_length(tbls) - 1 loop
    t := tbls->i;
    if jsonb_array_length(coalesce(t->'rows', '[]'::jsonb)) = 0 then
      report := report || jsonb_build_object(t->>'table', 0);
      continue;
    end if;
    select string_agg(quote_ident(a.attname), ', ' order by a.attnum)
      into cols
      from pg_attribute a
      where a.attrelid = ('public.' || quote_ident(t->>'table'))::regclass and a.attnum > 0 and not a.attisdropped
        and a.attgenerated = '' and (t->'rows'->0) ? a.attname;
    -- OVERRIDING SYSTEM VALUE: rows keep their original ids, including in
    -- tables whose id is GENERATED ALWAYS AS IDENTITY.
    execute format(
      'insert into public.%I (%s) overriding system value select %s from jsonb_populate_recordset(null::public.%I, (select jsonb_agg(e || jsonb_build_object(%L, $1)) from jsonb_array_elements($2) e))',
      t->>'table', cols, cols, t->>'table', t->>'col')
      using uid, t->'rows';
    get diagnostics n = row_count;
    report := report || jsonb_build_object(t->>'table', n);
  end loop;
  return report;
end
$function$
;
revoke all on function public.admin_import_player_rows(uid uuid, profile jsonb, tbls jsonb) from public, anon, authenticated;
grant execute on function public.admin_import_player_rows(uid uuid, profile jsonb, tbls jsonb) to service_role;

CREATE OR REPLACE FUNCTION public.admin_schema_snapshot()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  out jsonb := '{}'::jsonb;
begin
  -- sequences
  out := out || jsonb_build_object('sequences', coalesce((
    select jsonb_agg(format('create sequence if not exists public.%I;', c.relname) order by c.relname)
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind = 'S'), '[]'::jsonb));

  -- tables
  out := out || jsonb_build_object('tables', coalesce((
    select jsonb_agg(ddl order by name) from (
      select c.relname as name,
        format(E'create table if not exists public.%I (\n%s\n);', c.relname,
          string_agg(
            format('  %I %s%s%s', a.attname, format_type(a.atttypid, a.atttypmod),
              case
                when a.attgenerated = 's' then format(' generated always as (%s) stored', pg_get_expr(d.adbin, d.adrelid))
                when d.adbin is not null then ' default ' || pg_get_expr(d.adbin, d.adrelid)
                else '' end,
              case when a.attnotnull then ' not null' else '' end),
            E',\n' order by a.attnum)) as ddl
      from pg_class c
      join pg_namespace n on n.oid = c.relnamespace
      join pg_attribute a on a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped
      left join pg_attrdef d on d.adrelid = c.oid and d.adnum = a.attnum
      where n.nspname = 'public' and c.relkind in ('r', 'p')
      group by c.relname) t), '[]'::jsonb));

  -- constraints
  out := out || jsonb_build_object('constraints', coalesce((
    select jsonb_agg(format('alter table public.%I add constraint %I %s;', c.relname, con.conname, pg_get_constraintdef(con.oid))
      order by c.relname, case con.contype when 'p' then 0 when 'u' then 1 when 'c' then 2 else 3 end, con.conname)
    from pg_constraint con join pg_class c on c.oid = con.conrelid join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public'), '[]'::jsonb));

  -- indexes not backing a constraint
  out := out || jsonb_build_object('indexes', coalesce((
    select jsonb_agg(i.indexdef || ';' order by i.tablename, i.indexname)
    from pg_indexes i
    where i.schemaname = 'public'
      and not exists (select 1 from pg_constraint con where con.conname = i.indexname)), '[]'::jsonb));

  -- functions (not extension-owned)
  out := out || jsonb_build_object('functions', coalesce((
    select jsonb_agg(jsonb_build_object('name', p.proname, 'args', pg_get_function_identity_arguments(p.oid),
      'def', pg_get_functiondef(p.oid) || ';',
      'grants', coalesce((select jsonb_agg(distinct case when x.grantee = 0 then 'public' else x.grantee::regrole::text end)
        from aclexplode(p.proacl) x where x.privilege_type = 'EXECUTE'), '[]'::jsonb))
      order by p.proname, pg_get_function_identity_arguments(p.oid))
    from pg_proc p join pg_namespace n on n.oid = p.pronamespace
    where n.nspname = 'public' and p.prokind in ('f', 'p')
      and not exists (select 1 from pg_depend dep where dep.objid = p.oid and dep.deptype = 'e')), '[]'::jsonb));

  -- views and materialized views
  out := out || jsonb_build_object('views', coalesce((
    select jsonb_agg(case c.relkind
        when 'm' then format(E'create materialized view if not exists public.%I as\n%s', c.relname, pg_get_viewdef(c.oid, true))
        else format(E'create or replace view public.%I as\n%s', c.relname, pg_get_viewdef(c.oid, true)) end
      order by c.relname)
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind in ('v', 'm')), '[]'::jsonb));

  -- triggers (public tables, and auth.users)
  out := out || jsonb_build_object('triggers', coalesce((
    select jsonb_agg(pg_get_triggerdef(t.oid) || ';' order by c.relname, t.tgname)
    from pg_trigger t join pg_class c on c.oid = t.tgrelid join pg_namespace n on n.oid = c.relnamespace
    where not t.tgisinternal and (n.nspname = 'public' or (n.nspname = 'auth' and c.relname = 'users'))), '[]'::jsonb));

  -- row level security and policies
  out := out || jsonb_build_object('rls', coalesce((
    select jsonb_agg(format('alter table public.%I enable row level security;', c.relname) order by c.relname)
    from pg_class c join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public' and c.relkind = 'r' and c.relrowsecurity), '[]'::jsonb));
  out := out || jsonb_build_object('policies', coalesce((
    select jsonb_agg(format('create policy %I on public.%I as %s for %s to %s%s%s;',
        p.policyname, p.tablename, p.permissive, p.cmd, array_to_string(p.roles, ', '),
        case when p.qual is not null then ' using (' || p.qual || ')' else '' end,
        case when p.with_check is not null then ' with check (' || p.with_check || ')' else '' end)
      order by p.tablename, p.policyname)
    from pg_policies p where p.schemaname = 'public'), '[]'::jsonb));

  -- scheduled jobs
  out := out || jsonb_build_object('cron', coalesce((
    select jsonb_agg(jsonb_build_object('name', j.jobname, 'schedule', j.schedule, 'command', j.command) order by j.jobname)
    from cron.job j), '[]'::jsonb));

  -- extensions, realtime publication, storage buckets
  out := out || jsonb_build_object('extensions', coalesce((
    select jsonb_agg(e.extname order by e.extname) from pg_extension e), '[]'::jsonb));
  out := out || jsonb_build_object('realtime', coalesce((
    select jsonb_agg(pt.schemaname || '.' || pt.tablename) from pg_publication_tables pt where pt.pubname = 'supabase_realtime'), '[]'::jsonb));
  out := out || jsonb_build_object('buckets', coalesce((
    select jsonb_agg(jsonb_build_object('id', b.id, 'public', b.public)) from storage.buckets b), '[]'::jsonb));

  return out;
end
$function$
;
revoke all on function public.admin_schema_snapshot() from public, anon, authenticated;
grant execute on function public.admin_schema_snapshot() to service_role;

CREATE OR REPLACE FUNCTION public.admin_stats()
 RETURNS json
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with admins as (select id from profiles where is_admin is true)
  select json_build_object(
    'players',  (select count(*) from profiles where is_admin is not true),
    'members',  (select count(*) from profiles where is_admin is not true and is_premium and (premium_expires_at is null or premium_expires_at > now())),
    'activePlayers', (select count(*) from profiles where is_admin is not true and last_seen_at > now() - interval '7 days'),
    'badgesEarned', coalesce((select sum(coalesce(array_length(unlocked_badges, 1), 0)) from profiles where is_admin is not true), 0),
    'flex', json_build_object(
      'fishCaught', coalesce((select sum(catch_count) from fish_collection where user_id not in (select id from admins)), 0),
      'distanceSailed', coalesce((select sum(tide_run_total_distance) from profiles where is_admin is not true), 0),
      'biggestFish', coalesce(
        (select json_build_object(
          'length', pb.best_length_in,
          'species', fs.name,
          'username', p.username
        )
        from fish_personal_bests pb
        join fish_species fs on fs.id = pb.fish_id
        join profiles p on p.id = pb.user_id
        where pb.user_id not in (select id from admins)
        order by pb.best_length_in desc nulls last
        limit 1),
        '{}'::json
      ),
      'longestPerfectStreak', coalesce((select max(highest_perfect_streak) from profiles where is_admin is not true), 0),
      'longestPerfectStreakBy', (
        select username from profiles
        where is_admin is not true and highest_perfect_streak > 0
        order by highest_perfect_streak desc nulls last
        limit 1
      ),
      'biggestTavernPayout', coalesce(
        (select json_build_object(
          'amount', at.payout,
          'game', at.game,
          'username', p.username
        )
        from (
          select 'Slots' as game, payout, user_id from slot_spins where user_id not in (select id from admins)
          union all
          select 'Crown & Anchor' as game, payout, user_id from dice_rolls where user_id not in (select id from admins)
          union all
          select 'Blackjack' as game, net_delta as payout, user_id from blackjack_hands where user_id not in (select id from admins)
        ) at
        left join profiles p on p.id = at.user_id
        order by at.payout desc nulls last
        limit 1),
        '{}'::json
      )
    ),
    'fishing', json_build_object(
      'casts',    coalesce((select sum(fishing_casts) from profiles where is_admin is not true), 0),
      'perfects', coalesce((select sum(total_perfects) from profiles where is_admin is not true), 0),
      'caught',   coalesce((select sum(catch_count) from fish_collection where user_id not in (select id from admins)), 0),
      'species',  (select count(distinct fish_id) from fish_collection where user_id not in (select id from admins)),
      'jackpots', coalesce((select sum(fishing_jackpots) from profiles where is_admin is not true), 0),
      'doubles',  coalesce((select sum(fishing_double_catches) from profiles where is_admin is not true), 0),
      'snags',    coalesce((select sum(fishing_snags) from profiles where is_admin is not true), 0),
      'crates',   coalesce((select sum(fishing_crates_opened) from profiles where is_admin is not true), 0),
      'personalBests', (select count(*) from fish_personal_bests where user_id not in (select id from admins))
    ),
    -- Prestige — zone resets. Captains = players with at least one
    -- prestiged zone; stars = total stars lit fleet-wide (capped 5/zone,
    -- matching the badge math on /achievements).
    'prestige', json_build_object(
      'captains', (
        select count(*) from profiles p
        where p.is_admin is not true and exists (
          select 1 from jsonb_each_text(coalesce(p.prestige_levels, '{}'::jsonb)) v
          where (v.value)::int >= 1
        )
      ),
      'stars', coalesce((
        select sum(least(5, (v.value)::int))
        from profiles p, jsonb_each_text(coalesce(p.prestige_levels, '{}'::jsonb)) v
        where p.is_admin is not true
      ), 0)
    ),
    -- Goldens (1/1000 Perfect catches, terminal-state Sell or Mount).
    -- Each row in shiny_catches is one landed golden; status reflects
    -- the player's forced choice at the result moment.
    'goldens', json_build_object(
      'total',   (select count(*) from shiny_catches where user_id not in (select id from admins)),
      'mounted', (select count(*) from shiny_catches where status = 'mounted' and user_id not in (select id from admins)),
      'sold',    (select count(*) from shiny_catches where status = 'sold' and user_id not in (select id from admins)),
      'topCaptainCount', coalesce((
        select max(c) from (
          select count(*) as c from shiny_catches
          where user_id not in (select id from admins)
          group by user_id
        ) t
      ), 0),
      'topCaptainBy', (
        select p.username
        from shiny_catches sc
        join profiles p on p.id = sc.user_id
        where sc.user_id not in (select id from admins)
        group by p.username
        order by count(*) desc
        limit 1
      )
    ),
    'raids', json_build_object(
      'cleared',      (select count(*) from raid_completions where user_id not in (select id from admins)),
      'biggestHit',   coalesce((select max(highest_raid_damage) from profiles where is_admin is not true), 0),
      'biggestHitBy', (select username from profiles where is_admin is not true order by highest_raid_damage desc nulls last limit 1),
      'byBoss', (
        select coalesce(
          json_agg(json_build_object('raidId', raid_id, 'players', players, 'completions', completions) order by players desc),
          '[]'::json
        )
        from (
          select raid_id, count(distinct user_id)::int as players, count(*)::int as completions
          from raid_completions
          where user_id not in (select id from admins)
          group by raid_id
        ) t
      )
    ),
    'tideRun', json_build_object(
      'distance',      coalesce((select sum(tide_run_total_distance) from profiles where is_admin is not true), 0),
      'beacons',       coalesce((select sum(tide_run_beacons_smashed) from profiles where is_admin is not true), 0),
      'longest',       coalesce((select max(tide_run_best_distance) from profiles where is_admin is not true), 0),
      'longestBy',     (select username from profiles where is_admin is not true order by tide_run_best_distance desc nulls last limit 1),
      'mostBeacons',   coalesce((select max(tide_run_beacons_smashed) from profiles where is_admin is not true), 0),
      'mostBeaconsBy', (select username from profiles where is_admin is not true order by tide_run_beacons_smashed desc nulls last limit 1)
    ),
    'voyages', json_build_object(
      'completed', (select count(*) from daily_voyages where status = 'revealed' and user_id not in (select id from admins)),
      'loot',      coalesce((select sum(total_doubloons) from daily_voyages where status = 'revealed' and user_id not in (select id from admins)), 0),
      'crewLost',  coalesce((select sum(coalesce(array_length(crew_lost, 1), 0)) from daily_voyages where status = 'revealed' and user_id not in (select id from admins)), 0)
    ),
    'recruits', json_build_object(
      'lifetime',  coalesce((select sum(lifetime_recruits) from profiles where is_admin is not true), 0),
      'total',     (select count(*) from user_crew where died_at is null and user_id not in (select id from admins)),
      'legendary', (select count(*) from user_crew where rarity = 4 and died_at is null and user_id not in (select id from admins)),
      'epic',      (select count(*) from user_crew where rarity = 3 and died_at is null and user_id not in (select id from admins)),
      'rare',      (select count(*) from user_crew where rarity = 2 and died_at is null and user_id not in (select id from admins)),
      'common',    (select count(*) from user_crew where rarity = 1 and died_at is null and user_id not in (select id from admins)),
      'deployed',  (select count(*) from user_crew where (voyage_slot is not null or raid_slot is not null) and died_at is null and user_id not in (select id from admins)),
      'fallen',    (select count(*) from user_crew where died_at is not null and user_id not in (select id from admins)),
      'nicknamed', (select count(*) from user_crew where nickname is not null and died_at is null and user_id not in (select id from admins)),
      'topXP',     coalesce((select max(xp) from user_crew where died_at is null and user_id not in (select id from admins)), 0),
      'topXPBy',   (
        select p.username from user_crew uc
        join profiles p on p.id = uc.user_id
        where uc.died_at is null and uc.user_id not in (select id from admins)
        order by uc.xp desc nulls last
        limit 1
      ),
      -- Crew Hall ladder (tiers 1-5, default 1). Upgrades bought =
      -- total rungs climbed fleet-wide; hallMaxed = captains at tier 5.
      'hallUpgrades', coalesce((select sum(greatest(coalesce(crew_hall_tier, 1) - 1, 0)) from profiles where is_admin is not true), 0),
      'hallMaxed',    (select count(*) from profiles where is_admin is not true and crew_hall_tier >= 5)
    ),
    -- Tavern minigames. Slots is the long-runner; Blackjack is the
    -- main wager game now. Crown & Anchor (dice_rolls) was retired
    -- but the historical totals stay surfaced for reference.
    'tavern', json_build_object(
      'slotSpins',  (select count(*) from slot_spins where user_id not in (select id from admins)),
      'slotWins',   (select count(*) from slot_spins where payout > 0 and user_id not in (select id from admins)),
      'slotBiggest', coalesce((select max(payout) from slot_spins where user_id not in (select id from admins)), 0)
    ),
    -- Catfish Jackpot — single-row state table; history is only the
    -- last claim, so that's what we surface alongside the live pot.
    'jackpot', json_build_object(
      'pot',        coalesce((select pot from slots_jackpot limit 1), 0),
      'lastAmount', coalesce((select last_win_amount from slots_jackpot limit 1), 0),
      'lastBy',     (select last_winner_name from slots_jackpot limit 1),
      'lastAt',     (select last_won_at from slots_jackpot limit 1)
    ),
    -- The Den — shared casino chip wallet across blackjack / roulette /
    -- slots. Chips in play = un-cashed-out balances; buy-ins are the
    -- doubloons converted in (5k/day cap lives on casino_buy_ins).
    'den', json_build_object(
      'chipsHeld',  coalesce((select sum(casino_chips) from profiles where is_admin is not true), 0),
      'buyIns',     (select count(*) from casino_buy_ins where user_id not in (select id from admins)),
      'buyInTotal', coalesce((select sum(amount) from casino_buy_ins where user_id not in (select id from admins)), 0)
    ),
    'blackjack', json_build_object(
      'hands',         (select count(*) from blackjack_hands where user_id not in (select id from admins)),
      'totalWagered',  coalesce((select sum(total_wagered) from blackjack_hands where user_id not in (select id from admins)), 0),
      'biggestWin',    coalesce((select max(net_delta) from blackjack_hands where user_id not in (select id from admins)), 0),
      'biggestWinBy',  (
        select p.username from blackjack_hands bj
        join profiles p on p.id = bj.user_id
        where bj.user_id not in (select id from admins)
        order by bj.net_delta desc nulls last
        limit 1
      ),
      'biggestLoss',   coalesce((select abs(min(net_delta)) from blackjack_hands where net_delta < 0 and user_id not in (select id from admins)), 0),
      'biggestLossBy', (
        select p.username from blackjack_hands bj
        join profiles p on p.id = bj.user_id
        where bj.net_delta < 0 and bj.user_id not in (select id from admins)
        order by bj.net_delta asc nulls last
        limit 1
      )
    ),
    'roulette', json_build_object(
      'spins',         (select count(*) from roulette_spins where user_id not in (select id from admins)),
      'totalWagered',  coalesce((select sum(total_wagered) from roulette_spins where user_id not in (select id from admins)), 0),
      'biggestWin',    coalesce((select max(net_chips) from roulette_spins where user_id not in (select id from admins)), 0)
    ),
    -- The Parlor — trivia hub. Board = Captain's Board daily category
    -- column; ladder = Pirate King weekly 10-rung climb (crowned /
    -- walked / busted are the three terminal states).
    'parlor', json_build_object(
      'boardPlays',   (select count(*) from trivia_board_attempts where user_id not in (select id from admins)),
      'boardPayout',  coalesce((select sum(coalesce(doubloons_awarded, 0)) from trivia_board_attempts where user_id not in (select id from admins)), 0),
      'ladderRuns',   (select count(*) from trivia_ladder_attempts where user_id not in (select id from admins)),
      'kingsCrowned', (select count(*) from trivia_ladder_attempts where status = 'crowned' and user_id not in (select id from admins)),
      'walked',       (select count(*) from trivia_ladder_attempts where status = 'walked' and user_id not in (select id from admins)),
      'busted',       (select count(*) from trivia_ladder_attempts where status = 'busted' and user_id not in (select id from admins)),
      'ladderPayout', coalesce((select sum(coalesce(doubloons_awarded, 0)) from trivia_ladder_attempts where user_id not in (select id from admins)), 0)
    ),
    'mail', json_build_object(
      'messages', (select count(*) from mail_messages),
      'reads',    (select count(*) from mail_reads where user_id not in (select id from admins)),
      'claims',   (select count(*) from mail_reads where claimed_at is not null and user_id not in (select id from admins))
    ),
    -- Daily Challenges. claimed_1/2/3 booleans on each row; total
    -- completions = sum of trues across all three picks.
    'dailyChallenges', json_build_object(
      'completed', coalesce((
        select sum( (claimed_1::int) + (claimed_2::int) + (claimed_3::int) )
        from daily_challenge_progress
        where user_id not in (select id from admins)
      ), 0),
      'activeDays', (select count(distinct (user_id, date)) from daily_challenge_progress where user_id not in (select id from admins))
    ),
    'economy', json_build_object(
      'fishSold',        coalesce((select sum(amount) from doubloon_transactions where (reason like 'Sold fish%' or reason = 'Pending sale settled') and user_id not in (select id from admins)), 0),
      'doubloonsEarned', coalesce((select sum(amount) from doubloon_transactions where amount > 0 and reason <> 'Admin grant' and user_id not in (select id from admins)), 0),
      'doubloonsSpent',  coalesce((select -sum(amount) from doubloon_transactions where amount < 0 and user_id not in (select id from admins)), 0),
      'gemsEarned',      coalesce((select sum(amount) from gem_transactions where amount > 0 and reason <> 'Admin grant' and user_id not in (select id from admins)), 0),
      'doubloonsHeld',   coalesce((select sum(doubloons) from profiles where is_admin is not true), 0),
      'gemsHeld',        coalesce((select sum(gems) from profiles where is_admin is not true), 0),
      -- Patient sells = the 90%-in-1h delayed liquidate lane; count of
      -- settled payouts (transactions, not in-flight pending_sales rows).
      'patientSells',    (select count(*) from doubloon_transactions where reason = 'Pending sale settled' and user_id not in (select id from admins))
    )
  );
$function$
;
revoke all on function public.admin_stats() from public, anon, authenticated;
grant execute on function public.admin_stats() to anon;
grant execute on function public.admin_stats() to authenticated;
grant execute on function public.admin_stats() to public;
grant execute on function public.admin_stats() to service_role;

CREATE OR REPLACE FUNCTION public.bump_fish_lifetime(uid uuid, fid integer, n integer, at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into fish_lifetime (user_id, fish_id, catches, first_caught_at, last_caught_at)
  values (uid, fid, n, at, at)
  on conflict (user_id, fish_id) do update
    set catches        = fish_lifetime.catches + excluded.catches,
        first_caught_at = least(coalesce(fish_lifetime.first_caught_at, excluded.first_caught_at), excluded.first_caught_at),
        last_caught_at  = greatest(coalesce(fish_lifetime.last_caught_at, excluded.last_caught_at), excluded.last_caught_at);
end $function$
;
revoke all on function public.bump_fish_lifetime(uid uuid, fid integer, n integer, at timestamp with time zone) from public, anon, authenticated;
