CREATE OR REPLACE FUNCTION public.bump_profile_json_counter(uid uuid, col text, key text, n integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if col not in ('crate_opens', 'bait_used') then
    raise exception 'bump_profile_json_counter: % is not a counter map', col;
  end if;
  if key is null or key = '' or length(key) > 40 then
    raise exception 'bump_profile_json_counter: bad key';
  end if;
  execute format(
    'update profiles set %I = jsonb_set(coalesce(%I, ''{}''::jsonb), array[$1], '
    || 'to_jsonb(coalesce((%I -> $1)::int, 0) + $2), true) where id = $3',
    col, col, col
  ) using key, n, uid;
end $function$
;
revoke all on function public.bump_profile_json_counter(uid uuid, col text, key text, n integer) from public, anon, authenticated;
grant execute on function public.bump_profile_json_counter(uid uuid, col text, key text, n integer) to service_role;

