CREATE OR REPLACE FUNCTION public.check_rate_limit(p_key text, p_max integer, p_window_seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count INT;
  v_window_start TIMESTAMPTZ;
BEGIN
  SELECT count, window_start INTO v_count, v_window_start
  FROM rate_limits
  WHERE key = p_key
  FOR UPDATE;

  IF NOT FOUND OR NOW() > v_window_start + (p_window_seconds * INTERVAL '1 second') THEN
    INSERT INTO rate_limits (key, count, window_start)
    VALUES (p_key, 1, NOW())
    ON CONFLICT (key) DO UPDATE SET count = 1, window_start = NOW();
    RETURN TRUE;
  END IF;

  IF v_count >= p_max THEN
    RETURN FALSE;
  END IF;

  UPDATE rate_limits SET count = count + 1 WHERE key = p_key;
  RETURN TRUE;
END;
$function$
;
revoke all on function public.check_rate_limit(p_key text, p_max integer, p_window_seconds integer) from public, anon, authenticated;
grant execute on function public.check_rate_limit(p_key text, p_max integer, p_window_seconds integer) to service_role;

CREATE OR REPLACE FUNCTION public.claim_badge_reward(p_user uuid, p_badge text, p_amount integer, p_gems integer DEFAULT 0)
 RETURNS TABLE(new_doubloons bigint, new_gems bigint, claimed text[], granted boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  did_grant boolean := false;
begin
  update public.profiles
     set doubloons = doubloons + p_amount,
         gems = gems + p_gems,
         claimed_badge_rewards = array_append(claimed_badge_rewards, p_badge)
   where id = p_user
     and p_badge = any(coalesce(unlocked_badges, '{}'))
     and not (p_badge = any(coalesce(claimed_badge_rewards, '{}')));
  if found then did_grant := true; end if;

  return query
    select p.doubloons::bigint, p.gems::bigint, p.claimed_badge_rewards, did_grant
      from public.profiles p
     where p.id = p_user;
end;
$function$
;
revoke all on function public.claim_badge_reward(p_user uuid, p_badge text, p_amount integer, p_gems integer) from public, anon, authenticated;
grant execute on function public.claim_badge_reward(p_user uuid, p_badge text, p_amount integer, p_gems integer) to service_role;

