CREATE OR REPLACE FUNCTION public.claim_mail(uid uuid, mid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  msg RECORD;
  v_joined timestamptz;
  rows_affected int;
BEGIN
  SELECT id, attachment_gems, attachment_doubloons, target_user_id, evergreen, created_at
    INTO msg FROM mail_messages WHERE id = mid;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;

  -- Visibility guard (mirrors getInbox). Targeted mail is claimable only by its
  -- recipient; a non-evergreen broadcast only by players who joined on/before it
  -- was sent. Blocks claiming a hidden mail's reward via a crafted id.
  IF msg.target_user_id IS NOT NULL AND msg.target_user_id <> uid THEN
    RETURN jsonb_build_object('error', 'not_found');
  END IF;
  IF msg.target_user_id IS NULL AND NOT msg.evergreen THEN
    SELECT created_at INTO v_joined FROM auth.users WHERE id = uid;
    IF v_joined IS NULL OR msg.created_at < v_joined THEN
      RETURN jsonb_build_object('error', 'not_found');
    END IF;
  END IF;

  IF msg.attachment_gems = 0 AND msg.attachment_doubloons = 0 THEN
    RETURN jsonb_build_object('error', 'no_attachment');
  END IF;

  INSERT INTO mail_reads (user_id, message_id, read_at, claimed_at)
  VALUES (uid, mid, now(), now())
  ON CONFLICT (user_id, message_id) DO UPDATE
    SET claimed_at = EXCLUDED.claimed_at
    WHERE mail_reads.claimed_at IS NULL;

  GET DIAGNOSTICS rows_affected = ROW_COUNT;
  IF rows_affected = 0 THEN
    RETURN jsonb_build_object('error', 'already_claimed');
  END IF;

  UPDATE profiles
    SET gems = COALESCE(gems, 0) + msg.attachment_gems,
        doubloons = COALESCE(doubloons, 0) + msg.attachment_doubloons
    WHERE id = uid;

  RETURN jsonb_build_object(
    'ok', true,
    'gems', msg.attachment_gems,
    'doubloons', msg.attachment_doubloons
  );
END;
$function$
;
revoke all on function public.claim_mail(uid uuid, mid uuid) from public, anon, authenticated;
grant execute on function public.claim_mail(uid uuid, mid uuid) to service_role;

