CREATE OR REPLACE FUNCTION public.claim_token(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row   claim_tokens%rowtype;
  v_uid   uuid;
  v_email text;
  v_gems  integer;
begin
  v_uid := auth.uid();
  if v_uid is null then
    return jsonb_build_object('status', 'not_authenticated');
  end if;

  select email into v_email from auth.users where id = v_uid;
  select * into v_row from claim_tokens where token = p_token;
  if not found then
    return jsonb_build_object('status', 'not_found');
  end if;
  if v_row.status != 'pending' then
    return jsonb_build_object('status', 'already_claimed');
  end if;
  if v_row.expires_at is not null and v_row.expires_at < now() then
    return jsonb_build_object('status', 'expired');
  end if;
  if v_row.email is not null and lower(v_row.email) != lower(v_email) then
    return jsonb_build_object('status', 'email_mismatch');
  end if;

  -- THE CLAIM IS THE GUARD: two claims fired together both saw 'pending'
  -- above; only one of them flips it here.
  update claim_tokens
     set status = 'claimed', claimed_by = v_uid, claimed_at = now()
   where token = p_token and status = 'pending';
  if not found then
    return jsonb_build_object('status', 'already_claimed');
  end if;

  v_gems := v_row.packs_to_grant * 100;
  insert into profiles (id, gems)
    values (v_uid, v_gems)
    on conflict (id) do update
      set gems = profiles.gems + excluded.gems;

  return jsonb_build_object('status', 'ok', 'gems', v_gems, 'packs', v_row.packs_to_grant);
end;
$function$
;
revoke all on function public.claim_token(p_token text) from public, anon, authenticated;
grant execute on function public.claim_token(p_token text) to authenticated;
grant execute on function public.claim_token(p_token text) to service_role;

