CREATE OR REPLACE FUNCTION public.exchange_live_value(p_stake numeric, p_leverage numeric, p_move numeric, p_remaining numeric, p_term numeric)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  INV_SQRT_2PI constant double precision := 0.3989422804014327;
  HOUSE_EDGE   constant double precision := 0.08;
  v_s   double precision;
  v_z   double precision;
  v_t   double precision;
  v_p   double precision;
  v_pdf double precision;
  v_cdf double precision;
  v_exp double precision;
begin
  if p_leverage is null or p_leverage <= 0 then return 0; end if;
  -- At or past expiry it is worth its intrinsic value and nothing more, which
  -- is the same thing settle_exchange_contracts pays.
  if p_remaining is null or p_remaining <= 0 or p_term is null or p_term <= 0 then
    return greatest(0, round(p_stake * p_leverage * greatest(0, p_move)))::int;
  end if;

  v_s := ((1 - HOUSE_EDGE) / (INV_SQRT_2PI * p_leverage)) * sqrt(p_remaining::double precision / p_term::double precision);
  if not (v_s > 0) then
    return greatest(0, round(p_stake * p_leverage * greatest(0, p_move)))::int;
  end if;

  v_z   := p_move::double precision / v_s;
  v_pdf := INV_SQRT_2PI * exp(-0.5 * v_z * v_z);
  v_t   := 1 / (1 + 0.2316419 * abs(v_z));
  v_p   := v_pdf * v_t * (0.319381530 + v_t * (-0.356563782 + v_t * (1.781477937 + v_t * (-1.821255978 + v_t * 1.330274429))));
  v_cdf := case when v_z >= 0 then 1 - v_p else v_p end;
  v_exp := p_move::double precision * v_cdf + v_s * v_pdf;

  return greatest(0, round((p_stake * p_leverage)::double precision * v_exp))::int;
end $function$
;
revoke all on function public.exchange_live_value(p_stake numeric, p_leverage numeric, p_move numeric, p_remaining numeric, p_term numeric) from public, anon, authenticated;
grant execute on function public.exchange_live_value(p_stake numeric, p_leverage numeric, p_move numeric, p_remaining numeric, p_term numeric) to service_role;

CREATE OR REPLACE FUNCTION public.get_badge_rarity()
 RETURNS TABLE(badge_id text, pct real)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH players AS (
    SELECT unlocked_badges
    FROM profiles
    WHERE NOT COALESCE(is_admin, false)
      AND (COALESCE(fishing_xp, 0) > 0 OR COALESCE(expedition_xp, 0) > 0)
  ),
  total AS (SELECT GREATEST(count(*), 1)::real AS n FROM players)
  SELECT b AS badge_id,
         (count(*)::real / (SELECT n FROM total) * 100.0)::real AS pct
  FROM players p, unnest(p.unlocked_badges) AS b
  GROUP BY b;
$function$
;
revoke all on function public.get_badge_rarity() from public, anon, authenticated;
grant execute on function public.get_badge_rarity() to service_role;

