CREATE OR REPLACE FUNCTION public.grant_crew_xp_pairs(uid uuid, pairs jsonb)
 RETURNS TABLE(id bigint, old_xp integer, new_xp integer)
 LANGUAGE sql
 SET search_path TO 'public', 'pg_temp'
AS $function$
  update public.user_crew uc
  set xp = uc.xp + p.grant_xp
  from (
    select (e->>'id')::bigint as crew_id,
           (e->>'xp')::int    as grant_xp
    from jsonb_array_elements(pairs) e
  ) p
  where uc.user_id  = uid
    and uc.died_at is null
    and uc.id       = p.crew_id
    and p.grant_xp  > 0
  returning uc.id::bigint, (uc.xp - p.grant_xp)::int as old_xp, uc.xp::int as new_xp
$function$
;
revoke all on function public.grant_crew_xp_pairs(uid uuid, pairs jsonb) from public, anon, authenticated;
grant execute on function public.grant_crew_xp_pairs(uid uuid, pairs jsonb) to service_role;

