  SET xp = xp + grant_xp
  WHERE user_id = uid AND died_at IS NULL AND raid_slot IS NOT NULL
  RETURNING user_crew.id::bigint, (user_crew.xp - grant_xp)::int AS old_xp, user_crew.xp::int AS new_xp
