CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  insert into public.profiles (id)
  values (new.id)
  on conflict (id) do nothing;

  insert into public.bait_inventory (user_id, bait_type, quantity)
  values (new.id, 'worm', 25)
  on conflict (user_id, bait_type) do nothing;

  return new;
end;
$function$
;
revoke all on function public.handle_new_user() from public, anon, authenticated;
grant execute on function public.handle_new_user() to service_role;

CREATE OR REPLACE FUNCTION public.increment_doubloons(user_id uuid, amount integer)
 RETURNS integer
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update profiles
     set doubloons = doubloons + amount
   where id = user_id
  returning doubloons;
$function$
;
revoke all on function public.increment_doubloons(user_id uuid, amount integer) from public, anon, authenticated;
grant execute on function public.increment_doubloons(user_id uuid, amount integer) to service_role;

CREATE OR REPLACE FUNCTION public.increment_gems(user_id uuid, amount integer)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update profiles
  set gems = gems + amount
  where id = user_id;
$function$
;
revoke all on function public.increment_gems(user_id uuid, amount integer) from public, anon, authenticated;
grant execute on function public.increment_gems(user_id uuid, amount integer) to service_role;

CREATE OR REPLACE FUNCTION public.profile_array_add(uid uuid, col text, val text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int; t text;
begin
  select data_type into t from information_schema.columns
   where table_schema = 'public' and table_name = 'profiles' and column_name = col;
  if t = 'ARRAY' then
    execute format(
      'update public.profiles set %1$I = array_append(coalesce(%1$I, ''{}''), $2)
        where id = $1 and not ($2 = any(coalesce(%1$I, ''{}'')))', col)
      using uid, val;
  elsif t = 'jsonb' then
    execute format(
      'update public.profiles set %1$I = coalesce(%1$I, ''[]''::jsonb) || to_jsonb($2)
        where id = $1 and jsonb_typeof(coalesce(%1$I, ''[]''::jsonb)) = ''array''
          and not (coalesce(%1$I, ''[]''::jsonb) ? $2)', col)
      using uid, val;
  else
    raise exception 'profile_array_add: column % not allowed', col;
  end if;
  get diagnostics n = row_count;
  return n > 0;
end $function$
;
revoke all on function public.profile_array_add(uid uuid, col text, val text) from public, anon, authenticated;
grant execute on function public.profile_array_add(uid uuid, col text, val text) to service_role;

CREATE OR REPLACE FUNCTION public.raid_progress_board()
 RETURNS TABLE(user_id uuid, username text, score integer, last_at timestamp with time zone)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT s.user_id, s.username, s.score, s.last_at FROM (
    SELECT p.id AS user_id, p.username,
      (CASE WHEN jsonb_typeof((p.raid_node_progress)::jsonb -> 'cleared') = 'array'
            THEN jsonb_array_length((p.raid_node_progress)::jsonb -> 'cleared') ELSE 0 END
       + coalesce(rc.boss_count, 0)
       + CASE WHEN p.has_completed_practice_raid THEN 1 ELSE 0 END)::int AS score,
      rc.last_at
    FROM profiles p
    LEFT JOIN (
      SELECT user_id, count(DISTINCT raid_id)::int AS boss_count, max(completed_at) AS last_at
      FROM raid_completions GROUP BY user_id
    ) rc ON rc.user_id = p.id
    WHERE p.is_admin = false
  ) s
  WHERE s.score > 0
  ORDER BY s.score DESC, s.last_at ASC NULLS LAST;
$function$
;
revoke all on function public.raid_progress_board() from public, anon, authenticated;
grant execute on function public.raid_progress_board() to public;
grant execute on function public.raid_progress_board() to service_role;

CREATE OR REPLACE FUNCTION public.raid_records(uid uuid)
 RETURNS TABLE(raid_id text, fastest_username text, fastest_ms integer, total_clearers integer, your_best_ms integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH nonadmin AS (
    SELECT rc.raid_id, rc.user_id, rc.elapsed_ms, p.username
    FROM raid_completions rc
    JOIN profiles p ON p.id = rc.user_id
    WHERE coalesce(p.is_admin, false) = false
  ),
  fastest AS (
    SELECT DISTINCT ON (raid_id) raid_id, username AS fastest_username, elapsed_ms AS fastest_ms
    FROM nonadmin
    ORDER BY raid_id, elapsed_ms ASC NULLS LAST
  ),
  clearers AS (
    SELECT raid_id, count(DISTINCT user_id)::int AS total_clearers FROM nonadmin GROUP BY raid_id
  ),
  mine AS (
    SELECT raid_id, min(elapsed_ms)::int AS your_best_ms
    FROM raid_completions WHERE user_id = uid GROUP BY raid_id
  ),
  raids AS (
    SELECT raid_id FROM nonadmin UNION SELECT raid_id FROM mine
  )
  SELECT r.raid_id, f.fastest_username, f.fastest_ms::int,
         coalesce(c.total_clearers, 0)::int, m.your_best_ms
  FROM raids r
  LEFT JOIN fastest f ON f.raid_id = r.raid_id
  LEFT JOIN clearers c ON c.raid_id = r.raid_id
  LEFT JOIN mine m ON m.raid_id = r.raid_id;
$function$
;
revoke all on function public.raid_records(uid uuid) from public, anon, authenticated;
grant execute on function public.raid_records(uid uuid) to public;
grant execute on function public.raid_records(uid uuid) to service_role;

CREATE OR REPLACE FUNCTION public.record_gauntlet_depth_best(uid uuid, v text, hc boolean, d integer, ms integer)
 RETURNS TABLE(prev_ms integer, is_record boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare old_ms int;
begin
  if d < 1 or d > 100 or ms < 0 then
    return query select null::int, false;
    return;
  end if;

  select b.best_ms into old_ms
    from public.gauntlet_depth_bests b
   where b.user_id = uid and b.variant = v and b.hardcore = hc and b.depth = d;

  if old_ms is null then
    insert into public.gauntlet_depth_bests (user_id, variant, hardcore, depth, best_ms)
    values (uid, v, hc, d, ms)
    on conflict (user_id, variant, hardcore, depth) do nothing;
    -- First time this deep is not a "new best" -- there is nothing to have beaten,
    -- and the descent itself is already the moment. Caller tells them apart by
    -- prev_ms being null.
    return query select null::int, false;

  elsif ms < old_ms then
    update public.gauntlet_depth_bests b
       set best_ms = ms, achieved_at = now()
     where b.user_id = uid and b.variant = v and b.hardcore = hc and b.depth = d;
    return query select old_ms, true;

  else
    return query select old_ms, false;
  end if;
end $function$
;
revoke all on function public.record_gauntlet_depth_best(uid uuid, v text, hc boolean, d integer, ms integer) from public, anon, authenticated;
grant execute on function public.record_gauntlet_depth_best(uid uuid, v text, hc boolean, d integer, ms integer) to service_role;

