CREATE OR REPLACE FUNCTION public.set_default_username()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.username IS NULL THEN
    NEW.username := 'crew_' || LEFT(REPLACE(NEW.id::TEXT, '-', ''), 5);
  END IF;
  RETURN NEW;
END;
$function$
;
revoke all on function public.set_default_username() from public, anon, authenticated;
grant execute on function public.set_default_username() to anon;
grant execute on function public.set_default_username() to authenticated;
grant execute on function public.set_default_username() to public;
grant execute on function public.set_default_username() to service_role;

CREATE OR REPLACE FUNCTION public.settle_exchange_bets()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  b        record;
  v_exit   numeric;
  v_intr   numeric;
  v_payout bigint;
  v_count  integer := 0;
begin
  for b in
    select id from exchange_bets
     where status = 'open' and expires_at <= now()
     order by id limit 5000
  loop
    update exchange_bets set status = 'lost', settled_at = now()
     where id = b.id and status = 'open';
    if not found then continue; end if;

    declare bet exchange_bets%rowtype;
    begin
      select * into bet from exchange_bets where id = b.id;
      select price into v_exit from exchange_indexes where id = bet.index_id;
      if v_exit is null then v_exit := bet.entry_price; end if;

      -- Vanilla payoff, times the units ONE contract covers. A contract on a
      -- cheap index covers hundreds of them, the way a real option is written
      -- on a hundred shares.
      v_intr := case when bet.direction = 'up'
                     then v_exit - bet.strike
                     else bet.strike - v_exit end;
      v_payout := greatest(0, floor(bet.units * coalesce(bet.lot, 1) * greatest(v_intr, 0)))::bigint;

      update exchange_bets
         set status = case when v_payout > bet.stake then 'won' else 'lost' end,
             exit_price = v_exit, payout = v_payout
       where id = bet.id;

      if v_payout > 0 then
        update profiles set doubloons = doubloons + v_payout where id = bet.user_id;
        insert into doubloon_transactions (user_id, amount, reason)
        values (bet.user_id, v_payout, 'Exchange contract settled');
      end if;
      v_count := v_count + 1;
    end;
  end loop;
  return v_count;
end
$function$
;
revoke all on function public.settle_exchange_bets() from public, anon, authenticated;
grant execute on function public.settle_exchange_bets() to service_role;

CREATE OR REPLACE FUNCTION public.slots_claim_jackpot(p_user_id uuid, p_winner_name text, p_wager integer, p_max_bet integer)
 RETURNS TABLE(share integer, new_pot integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_share int;
  v_new int;
begin
  if p_max_bet is null or p_max_bet <= 0 then
    raise exception 'invalid max bet';
  end if;

  update public.slots_jackpot
  set last_win_amount = floor(pot * least(greatest(coalesce(p_wager, 0), 0), p_max_bet)::numeric / p_max_bet)::int,
      pot = greatest(seed, pot - floor(pot * least(greatest(coalesce(p_wager, 0), 0), p_max_bet)::numeric / p_max_bet)::int),
      last_winner_id = p_user_id,
      last_winner_name = p_winner_name,
      last_won_at = now(),
      updated_at = now()
  where id = 1
  returning last_win_amount, pot into v_share, v_new;

  return query select v_share, v_new;
end;
$function$
;
revoke all on function public.slots_claim_jackpot(p_user_id uuid, p_winner_name text, p_wager integer, p_max_bet integer) from public, anon, authenticated;
grant execute on function public.slots_claim_jackpot(p_user_id uuid, p_winner_name text, p_wager integer, p_max_bet integer) to service_role;

CREATE OR REPLACE FUNCTION public.slots_feed_jackpot(p_amount integer)
 RETURNS integer
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
  update public.slots_jackpot
  set pot = pot + greatest(coalesce(p_amount, 0), 0),
      updated_at = now()
  where id = 1
  returning pot;
$function$
;
revoke all on function public.slots_feed_jackpot(p_amount integer) from public, anon, authenticated;
grant execute on function public.slots_feed_jackpot(p_amount integer) to service_role;

CREATE OR REPLACE FUNCTION public.trawl_admin_stats()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  select jsonb_build_object(
    'activeNow',        (select count(*) from public.trawls),
    'readyToCollect',   (select count(*) from public.trawls where ends_at <= now()),
    'captainsTrawling', (select count(distinct user_id) from public.trawls),
    'activeByZone', (
      select coalesce(jsonb_agg(jsonb_build_object('zone', zone, 'count', c) order by c desc), '[]'::jsonb)
      from (select zone, count(*) c from public.trawls group by zone) z
    ),
    'collections',     (select count(*) from public.doubloon_transactions where reason like 'Crew trawl:%'),
    'totalDoubloons',  (select coalesce(sum(amount), 0) from public.doubloon_transactions where reason like 'Crew trawl:%'),
    'avgDoubloons',    (select coalesce(round(avg(amount)), 0) from public.doubloon_transactions where reason like 'Crew trawl:%'),
    'uniqueCaptains',  (select count(distinct user_id) from public.doubloon_transactions where reason like 'Crew trawl:%'),
    'collections24h',  (select count(*) from public.doubloon_transactions where reason like 'Crew trawl:%' and created_at >= now() - interval '24 hours'),
    'doubloons24h',    (select coalesce(sum(amount), 0) from public.doubloon_transactions where reason like 'Crew trawl:%' and created_at >= now() - interval '24 hours'),
    'collections7d',   (select count(*) from public.doubloon_transactions where reason like 'Crew trawl:%' and created_at >= now() - interval '7 days'),
    'doubloons7d',     (select coalesce(sum(amount), 0) from public.doubloon_transactions where reason like 'Crew trawl:%' and created_at >= now() - interval '7 days'),
    'byZone', (
      select coalesce(jsonb_agg(jsonb_build_object('label', label, 'collections', c, 'doubloons', d) order by d desc), '[]'::jsonb)
      from (
        select substring(reason from 'Crew trawl: (.*)') as label, count(*) c, sum(amount) d
        from public.doubloon_transactions where reason like 'Crew trawl:%' group by reason
      ) z
    )
  );
$function$
;
revoke all on function public.trawl_admin_stats() from public, anon, authenticated;
grant execute on function public.trawl_admin_stats() to service_role;

CREATE OR REPLACE FUNCTION public.update_exchange_indexes()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  TREND_MAX  constant double precision := 0.0018;
  MAX_BIAS   constant double precision := 0.0125;
  DRIFT_K    constant double precision := 0.05;
  JUMP_P     constant double precision := 0.002;
  EVENT_MIN_DAYS constant double precision := 3;
  EVENT_MAX_DAYS constant double precision := 9;
  -- One gap in twenty goes far past the band. Lockstep with EXTREME_* in
  -- lib/exchangeBoard.ts. Capped: a price cannot fall further than all of it.
  EXTREME_P   constant double precision := 0.05;
  EXTREME_MIN constant double precision := 2;
  EXTREME_MAX constant double precision := 5;
  EXTREME_CAP constant double precision := 0.85;
  v_mood text; v_bias double precision; v_moodv double precision; r record;
  v_lp double precision; v_vol double precision; v_beta double precision;
  v_noise double precision; v_trend double precision; v_drift double precision;
  v_price double precision; v_ticks int; v_hist jsonb;
  v_jump double precision; v_note text; v_due boolean; v_next timestamptz;
  v_daily double precision; v_jmin double precision; v_jmax double precision;
  v_up   constant text[] := array[
    'a record haul reported', 'the shoals came back early', 'a rival fleet ran aground',
    'word of a bumper season', 'the nets came up heavy'];
  v_down constant text[] := array[
    'the beds came up empty', 'a spill fouled the grounds', 'the season closed early',
    'word of a die-off', 'the fleet found nothing'];
  v_flat constant text[] := array[
    'the count came in as expected', 'no change on the grounds', 'a quiet season, all told',
    'the books balanced, nothing more'];
  v_boom constant text[] := array[
    'a buyer took the whole fleet', 'the mother lode, and nobody saw it coming',
    'a new ground opened, and it is enormous'];
  v_bust constant text[] := array[
    'the grounds are fished out', 'the whole season written off',
    'the books were a lie, and the beds are bare'];
begin
  select mood, coalesce(mood_bias, 0)::double precision into v_mood, v_bias
    from market_state where id = 1;
  v_bias := coalesce(v_bias, 0) * 0.5;
  v_moodv := case v_mood when 'storm' then 1.5 when 'kraken' then 2.0
    when 'bounty_season' then 1.2 when 'cursed_waters' then 1.2 else 1.0 end;

  for r in select * from exchange_indexes loop
    v_vol := coalesce(r.vol, 0.05)::double precision;
    v_beta := coalesce(r.beta, 1.0)::double precision;
    v_price := coalesce(r.price, 1.0)::double precision;
    if not (v_price > 0) then v_price := 1.0; end if;
    v_lp := ln(v_price);
    v_trend := coalesce(r.trend, 0)::double precision;
    v_ticks := coalesce(r.trend_ticks, 0);
    v_next := r.next_event_at;

    if v_ticks <= 0 then
      v_trend := TREND_MAX * (0.35 + random() * 0.65)
                 * case when random() < 0.5 then 1 else -1 end;
      v_ticks := 72 + floor(random() * 264)::int;
    end if;

    v_drift := v_vol * DRIFT_K * (v_beta * (v_bias / MAX_BIAS) + v_trend / TREND_MAX);
    v_noise := (random() + random() + random() - 1.5) * v_vol * v_moodv;
    v_lp := v_lp + v_drift + v_noise;

    v_daily := v_vol * 2.449 * 100;
    v_jmin := greatest(3, least(15, 2 * v_daily)) / 100;
    v_jmax := greatest(8, least(40, 5 * v_daily)) / 100;
    if v_jmax <= v_jmin then v_jmax := v_jmin + 0.01; end if;

    v_due := v_next is not null and v_next <= now();
    v_jump := 0;
    if v_due then
      v_jump := random() * v_jmax;                          -- a report may say nothing
    elsif random() < JUMP_P then
      v_jump := v_jmin + random() * (v_jmax - v_jmin);      -- a surprise is news by definition
    end if;

    if v_jump <> 0 then
      -- THE TAIL. Rare, and it can take a price most of the way to nothing.
      if random() < EXTREME_P then
        v_jump := least(v_jump * (EXTREME_MIN + random() * (EXTREME_MAX - EXTREME_MIN)), EXTREME_CAP);
      end if;
      if random() < 0.5 then v_jump := -v_jump; end if;
      v_lp := v_lp + ln(1 + v_jump);

      if abs(v_jump) >= v_jmax * EXTREME_MIN then
        v_note := case when v_jump > 0
          then v_boom[1 + floor(random() * array_length(v_boom, 1))::int]
          else v_bust[1 + floor(random() * array_length(v_bust, 1))::int] end;
      elsif abs(v_jump) * 100 < greatest(0.4, v_daily * 0.5) then
        v_note := v_flat[1 + floor(random() * array_length(v_flat, 1))::int];
      elsif v_jump > 0 then
        v_note := v_up[1 + floor(random() * array_length(v_up, 1))::int];
      else
        v_note := v_down[1 + floor(random() * array_length(v_down, 1))::int];
      end if;
    end if;

    if v_due then
      v_next := now() + ((EVENT_MIN_DAYS + random() * (EVENT_MAX_DAYS - EVENT_MIN_DAYS))
                         || ' days')::interval;
    end if;

    v_price := exp(v_lp);
    if v_price is null or v_price <> v_price or v_price < 1e-12 or v_price > 1e15 then
      v_price := greatest(1e-12::double precision, least(1e15::double precision,
                   coalesce(nullif(v_price, 'NaN'::double precision), 1.0)));
    end if;

    v_hist := coalesce(r.history, '[]'::jsonb) || to_jsonb(round(coalesce(r.price, 1.0), 8));
    if jsonb_array_length(v_hist) > 48 then
      v_hist := (select jsonb_agg(elem order by ord) from (
        select elem, ord from jsonb_array_elements(v_hist) with ordinality as t(elem, ord)
        order by ord desc limit 48) sub);
    end if;

    update exchange_indexes set
      prev_price = price, price = round(v_price::numeric, 8),
      trend = v_trend, trend_ticks = v_ticks - 1,
      history = v_hist, updated_at = now(), next_event_at = v_next,
      last_event_at  = case when v_jump <> 0 then now() else last_event_at end,
      last_event     = case when v_jump <> 0 then v_note else last_event end,
      last_event_pct = case when v_jump <> 0 then round((v_jump * 100)::numeric, 1) else last_event_pct end
    where id = r.id;
  end loop;
end
$function$
;
revoke all on function public.update_exchange_indexes() from public, anon, authenticated;
grant execute on function public.update_exchange_indexes() to service_role;

CREATE OR REPLACE FUNCTION public.update_fish_market()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_mood text;
  v_mood_bias numeric;
  v_mood_expires_at timestamptz;
  v_roll float;
  r RECORD;
  v_volatility float;
  v_drift float;
  v_noise float;
  v_new_mult float;
  v_history jsonb;
BEGIN
  SELECT mood, mood_bias, mood_expires_at
    INTO v_mood, v_mood_bias, v_mood_expires_at
    FROM market_state WHERE id = 1;

  IF v_mood_expires_at IS NULL OR now() >= v_mood_expires_at THEN
    v_roll := random();
    IF v_roll < 0.05 THEN
      -- Kraken: extreme volatility, bidirectional
      v_mood := 'kraken';
      v_mood_bias := CASE WHEN random() < 0.5 THEN 0.02 ELSE -0.02 END;
      v_mood_expires_at := now() + (2 + floor(random() * 4)) * interval '1 hour';
    ELSIF v_roll < 0.10 THEN
      -- Bounty Season: strong bull
      v_mood := 'bounty_season';
      v_mood_bias := 0.025;
      v_mood_expires_at := now() + (2 + floor(random() * 4)) * interval '1 hour';
    ELSIF v_roll < 0.16 THEN
      -- Cursed Waters: strong bear
      v_mood := 'cursed_waters';
      v_mood_bias := -0.025;
      v_mood_expires_at := now() + (2 + floor(random() * 4)) * interval '1 hour';
    ELSIF v_roll < 0.28 THEN
      -- Tide Rising: weak bull
      v_mood := 'tide_rising';
      v_mood_bias := 0.012;
      v_mood_expires_at := now() + (2 + floor(random() * 4)) * interval '1 hour';
    ELSIF v_roll < 0.40 THEN
      -- Low Tide: weak bear
      v_mood := 'low_tide';
      v_mood_bias := -0.012;
      v_mood_expires_at := now() + (2 + floor(random() * 4)) * interval '1 hour';
    ELSIF v_roll < 0.60 THEN
      -- Storm: high volatility, bidirectional
      v_mood := 'storm';
      v_mood_bias := CASE WHEN random() < 0.5 THEN 0.01 ELSE -0.01 END;
      v_mood_expires_at := now() + (2 + floor(random() * 4)) * interval '1 hour';
    ELSE
      -- Calm: stable
      v_mood := 'calm';
      v_mood_bias := 0;
      v_mood_expires_at := now() + (2 + floor(random() * 4)) * interval '1 hour';
    END IF;

    UPDATE market_state SET
      mood = v_mood,
      mood_bias = v_mood_bias,
      mood_expires_at = v_mood_expires_at,
      next_update_at = now() + interval '1 hour'
    WHERE id = 1;
  ELSE
    UPDATE market_state SET
      next_update_at = now() + interval '1 hour'
    WHERE id = 1;
  END IF;

  FOR r IN
    SELECT fm.fish_id, fm.multiplier, fm.history, fs.bite_rarity
      FROM fish_market fm
      JOIN fish_species fs ON fs.id = fm.fish_id
  LOOP
    CASE r.bite_rarity
      WHEN 1 THEN v_volatility := 0.04;
      WHEN 2 THEN v_volatility := 0.06;
      WHEN 3 THEN v_volatility := 0.09;
      WHEN 4 THEN v_volatility := 0.14;
      ELSE        v_volatility := 0.20;
    END CASE;

    IF v_mood = 'storm' THEN
      v_volatility := v_volatility * 1.5;
    ELSIF v_mood = 'kraken' THEN
      v_volatility := v_volatility * 2.0;
    ELSIF v_mood IN ('bounty_season', 'cursed_waters') THEN
      v_volatility := v_volatility * 1.2;
    END IF;

    v_drift := 0.08 * (1.0 - r.multiplier::float);
    v_noise := (random() + random() + random() - 1.5) * v_volatility;

    v_new_mult := GREATEST(0.40, LEAST(2.50,
      r.multiplier::float + v_drift + v_noise + v_mood_bias::float
    ));

    v_history := r.history;
    v_history := v_history || to_jsonb(round(r.multiplier::numeric, 2));
    IF jsonb_array_length(v_history) > 24 THEN
      v_history := (SELECT jsonb_agg(elem ORDER BY ord) FROM (
        SELECT elem, ord FROM jsonb_array_elements(v_history) WITH ORDINALITY AS t(elem, ord)
        ORDER BY ord DESC LIMIT 24
      ) sub);
    END IF;

    UPDATE fish_market SET
      prev_multiplier = multiplier,
      multiplier = round(v_new_mult::numeric, 2),
      history = v_history,
      updated_at = now()
    WHERE fish_id = r.fish_id;
  END LOOP;
END;
$function$
;
revoke all on function public.update_fish_market() from public, anon, authenticated;
grant execute on function public.update_fish_market() to anon;
grant execute on function public.update_fish_market() to authenticated;
grant execute on function public.update_fish_market() to public;
grant execute on function public.update_fish_market() to service_role;

CREATE OR REPLACE FUNCTION public.upsert_bait(p_user_id uuid, p_bait_type text, p_qty integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO bait_inventory (user_id, bait_type, quantity)
  VALUES (p_user_id, p_bait_type, p_qty)
  ON CONFLICT (user_id, bait_type)
  DO UPDATE SET quantity = bait_inventory.quantity + EXCLUDED.quantity;
END;
$function$
;
revoke all on function public.upsert_bait(p_user_id uuid, p_bait_type text, p_qty integer) from public, anon, authenticated;
grant execute on function public.upsert_bait(p_user_id uuid, p_bait_type text, p_qty integer) to service_role;

CREATE OR REPLACE FUNCTION public.vigil_total(v jsonb)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public'
AS $function$
  select coalesce(sum(greatest(0, least(5, (value->>'rank')::int))), 0)::int
  from jsonb_each(coalesce(v, '{}'::jsonb))
$function$
;
revoke all on function public.vigil_total(v jsonb) from public, anon, authenticated;
grant execute on function public.vigil_total(v jsonb) to anon;
grant execute on function public.vigil_total(v jsonb) to authenticated;
grant execute on function public.vigil_total(v jsonb) to public;
grant execute on function public.vigil_total(v jsonb) to service_role;

CREATE OR REPLACE FUNCTION public.wallet_add(uid uuid, col text, delta bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v bigint;
begin
  if col not in ('doubloons','gems','blood_gems','gauntlet_fathoms','casino_chips') then
    raise exception 'wallet_add: column % not allowed', col;
  end if;
  execute format(
    'update public.profiles set %1$I = %1$I + $2 where id = $1 and %1$I + $2 >= 0 returning %1$I', col)
    into v using uid, delta;
  return v;  -- null = not enough (or no such player): nothing changed
end $function$
;
revoke all on function public.wallet_add(uid uuid, col text, delta bigint) from public, anon, authenticated;
grant execute on function public.wallet_add(uid uuid, col text, delta bigint) to service_role;
